import "core-js/modules/esnext.iterator.constructor.js";
import "core-js/modules/esnext.iterator.filter.js";
import "core-js/modules/esnext.iterator.map.js";
import { ref, computed, onMounted, watch } from "vue";
import { db } from "@/firebase";
import { collection, getDocs, query, where, Timestamp } from "firebase/firestore";
export default {
  name: "ApprovedPurchases",
  setup() {
    // State variables remain unchanged
    const approvedPurchases = ref([]);
    const loading = ref(true);
    const error = ref(null);
    const searchQuery = ref("");
    const dateFilter = ref("all");
    const sortBy = ref("dateDesc");
    const currentPage = ref(1);
    const itemsPerPage = ref(10);
    const selectedPurchase = ref(null);

    // Updated fetch function with debug logging
    const fetchApprovedPurchases = async () => {
      loading.value = true;
      error.value = null;
      try {
        console.log("Fetching approved purchases...");

        // Query with capital "A" in "Approved"
        const q = query(collection(db, "purchaseRequests"), where("status", "==", "Approved"));
        console.log("Query created, executing...");
        const querySnapshot = await getDocs(q);
        console.log(`Query returned ${querySnapshot.size} documents`);
        if (querySnapshot.empty) {
          console.log("No approved purchases found");
          approvedPurchases.value = [];
        } else {
          approvedPurchases.value = querySnapshot.docs.map(doc => {
            const data = doc.data();
            console.log("Document data:", data);

            // Generate a request ID if not present
            if (!data.requestId) {
              data.requestId = `PR-${doc.id.substring(0, 6).toUpperCase()}`;
            }

            // Handle Timestamp objects properly
            const createdAt = data.createdAt instanceof Timestamp ? data.createdAt.toDate() : data.createdAt ? new Date(data.createdAt) : new Date();
            const updatedAt = data.updatedAt instanceof Timestamp ? data.updatedAt.toDate() : data.updatedAt ? new Date(data.updatedAt) : new Date();
            const approvalDate = data.approvalDate instanceof Timestamp ? data.approvalDate.toDate() : data.approvalDate ? new Date(data.approvalDate) : updatedAt;
            return {
              id: doc.id,
              ...data,
              itemName: data.itemName || "Unnamed Item",
              category: data.category || "Uncategorized",
              quantity: data.quantity || 0,
              approvedBy: data.approvedBy || "System",
              createdAt: createdAt,
              updatedAt: updatedAt,
              dateApproved: approvalDate
            };
          });
          console.log(`Processed ${approvedPurchases.value.length} approved purchases`);
        }
      } catch (err) {
        console.error("Error fetching approved purchases:", err);
        error.value = "Failed to load approved purchases. Please try again.";
      } finally {
        loading.value = false;
      }
    };

    // Rest of the code remains unchanged
    const formatDate = date => {
      if (!date) return "N/A";
      const dateObj = date instanceof Date ? date : new Date(date);
      if (isNaN(dateObj.getTime())) return "Invalid Date";
      return dateObj.toLocaleDateString("en-US", {
        year: "numeric",
        month: "long",
        day: "numeric"
      });
    };

    // Filter purchases based on search query and date filter
    const filteredPurchases = computed(() => {
      let filtered = [...approvedPurchases.value];

      // Apply search filter
      if (searchQuery.value.trim()) {
        const query = searchQuery.value.toLowerCase().trim();
        filtered = filtered.filter(purchase => purchase.itemName?.toLowerCase().includes(query) || purchase.requestId?.toLowerCase().includes(query) || purchase.id.toLowerCase().includes(query));
      }

      // Apply date filter
      if (dateFilter.value !== "all") {
        const now = new Date();
        let startDate;
        switch (dateFilter.value) {
          case "today":
            {
              startDate = new Date(now.setHours(0, 0, 0, 0));
              break;
            }
          case "week":
            {
              startDate = new Date(now.setDate(now.getDate() - now.getDay()));
              break;
            }
          case "month":
            {
              startDate = new Date(now.getFullYear(), now.getMonth(), 1);
              break;
            }
          case "quarter":
            {
              const quarter = Math.floor(now.getMonth() / 3);
              startDate = new Date(now.getFullYear(), quarter * 3, 1);
              break;
            }
          case "year":
            {
              startDate = new Date(now.getFullYear(), 0, 1);
              break;
            }
          default:
            {
              startDate = new Date(0); // Default to epoch start
            }
        }
        filtered = filtered.filter(purchase => {
          const purchaseDate = purchase.dateApproved instanceof Date ? purchase.dateApproved : new Date(purchase.dateApproved || purchase.updatedAt || Date.now());
          return purchaseDate >= startDate;
        });
      }

      // Apply sorting
      filtered.sort((a, b) => {
        switch (sortBy.value) {
          case "dateAsc":
            {
              return new Date(a.dateApproved || a.updatedAt || 0) - new Date(b.dateApproved || b.updatedAt || 0);
            }
          case "dateDesc":
            {
              return new Date(b.dateApproved || b.updatedAt || 0) - new Date(a.dateApproved || a.updatedAt || 0);
            }
          case "nameAsc":
            {
              return (a.itemName || "").localeCompare(b.itemName || "");
            }
          case "nameDesc":
            {
              return (b.itemName || "").localeCompare(a.itemName || "");
            }
          case "quantityAsc":
            {
              return (a.quantity || 0) - (b.quantity || 0);
            }
          case "quantityDesc":
            {
              return (b.quantity || 0) - (a.quantity || 0);
            }
          default:
            {
              return 0;
            }
        }
      });
      return filtered;
    });
    const totalPages = computed(() => {
      return Math.max(1, Math.ceil(filteredPurchases.value.length / itemsPerPage.value));
    });
    const paginatedPurchases = computed(() => {
      const startIndex = (currentPage.value - 1) * itemsPerPage.value;
      const endIndex = startIndex + itemsPerPage.value;
      return filteredPurchases.value.slice(startIndex, endIndex);
    });
    const nextPage = () => {
      if (currentPage.value < totalPages.value) {
        currentPage.value++;
      }
    };
    const prevPage = () => {
      if (currentPage.value > 1) {
        currentPage.value--;
      }
    };

    // Reset to first page when filters change
    watch([searchQuery, dateFilter, sortBy], () => {
      currentPage.value = 1;
    });

    // Handle search
    const handleSearch = () => {
      currentPage.value = 1;
    };

    // Reset filters
    const resetFilters = () => {
      searchQuery.value = "";
      dateFilter.value = "all";
      sortBy.value = "dateDesc";
      currentPage.value = 1;
    };

    // View purchase details
    const viewPurchaseDetails = purchase => {
      selectedPurchase.value = purchase;
    };

    // Close modal
    const closeModal = () => {
      selectedPurchase.value = null;
    };

    // Download PDF
    const downloadPDF = purchase => {
      console.log("Downloading PDF for purchase:", purchase.id);
      alert(`PDF download for ${purchase.itemName} would start here.`);
    };

    // Fetch data on component mount
    onMounted(fetchApprovedPurchases);
    return {
      approvedPurchases,
      loading,
      error,
      searchQuery,
      dateFilter,
      sortBy,
      currentPage,
      filteredPurchases,
      paginatedPurchases,
      totalPages,
      selectedPurchase,
      formatDate,
      fetchApprovedPurchases,
      handleSearch,
      resetFilters,
      nextPage,
      prevPage,
      viewPurchaseDetails,
      closeModal,
      downloadPDF
    };
  }
};
